// Scoped first-paint release: preserve both current owners and every unrelated
// module. All uploads and deployment intents are durable before the next step.
import assert from 'node:assert/strict';import{readFileSync,writeFileSync,existsSync}from'node:fs';import{createHash}from'node:crypto';
const phase=process.argv[2],file='first-paint-publication-state.json',account='9e5386dcf455be34c582d93f8bfc79e6',zone='66ec3268950adcfc837b7b8b2f8356ed';
const definitions=[
{name:'shift-programme-member-20261023',kind:'programme',expectedDeployment:'0d7e4ed6-2be3-4b4a-bf68-ca64d7bb3804',expectedVersion:'742bfb7e-7743-4cbc-84d5-187177488ce9',expectedFactory:'f4c0a6e6de80d123a94c1d709891c2106a279ea844baead7ec4a0424e8072321'},
{name:'shift-hq-member-comms-20261023',kind:'documents',expectedDeployment:'05b5f637-5ac3-4920-a87f-062772124160',expectedVersion:'459dd83d-9ade-461f-997a-6e11a4d7d3ff',expectedFactory:'4e8e63f984a5a266aee61fa6d76fcca2a9d4050d433c23d1f945bc5647ed1841'}];
const auth=readFileSync('/Users/shiftsometimberltd/Library/Preferences/.wrangler/config/default.toml','utf8'),token=process.env.CLOUDFLARE_API_TOKEN||auth.match(/^oauth_token\s*=\s*"([^"\n]+)"/m)?.[1];assert(token);
const digest=b=>createHash('sha256').update(b).digest('hex'),hashes=ms=>Object.fromEntries(ms.map(m=>[m.name,digest(Buffer.from(m.content_base64,'base64'))]).sort(([a],[b])=>a.localeCompare(b))),sorted=b=>[...b].sort((a,b)=>a.name.localeCompare(b.name));
let state=existsSync(file)?JSON.parse(readFileSync(file,'utf8')):{kind:'MY_TIMBER_FIRST_PAINT_RELEASE',createdAt:new Date().toISOString(),owners:[]};
const save=()=>writeFileSync(file,JSON.stringify(state,null,2)+'\n'),ep=n=>'/accounts/'+account+'/workers/scripts/'+n;
async function cf(path,method='GET',body){const multi=body instanceof FormData,r=await fetch('https://api.cloudflare.com/client/v4'+path,{method,headers:{Authorization:'Bearer '+token,...(body&&!multi?{'Content-Type':'application/json'}:{})},body:multi?body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(55000)}),j=await r.json();assert(r.ok&&j.success,method+' '+path+': '+JSON.stringify(j.errors));return j.result;}
const active=async n=>[...(await cf(ep(n)+'/deployments')).deployments].sort((a,b)=>b.created_on.localeCompare(a.created_on))[0];
const version=(n,id)=>cf('/accounts/'+account+'/workers/workers/'+n+'/versions/'+id+'?include=modules'),routes=()=>cf('/zones/'+zone+'/workers/routes');
async function guard(){for(const s of state.owners)assert.equal((await active(s.name)).id,s.currentDeployment,'Concurrent deployment: '+s.name);assert.deepEqual(await routes(),state.routes,'Concurrent routes changed');for(const s of state.owners)assert.deepEqual(await cf(ep(s.name)+'/schedules'),s.schedules,'Schedules changed: '+s.name);}
async function preserved(s,v){assert.equal(v.main_module,s.mainModule);assert.deepEqual(sorted(v.bindings),sorted(s.bindings));assert.equal(v.compatibility_date,s.compatibilityDate);assert.deepEqual(v.compatibility_flags||[],s.compatibilityFlags);assert.deepEqual(v.assets??v.resources?.script_runtime?.assets,s.assets);let settings;for(const[k,x]of Object.entries(s.operatingConfiguration)){let actual=v[k]??v.resources?.script_runtime?.[k];if(actual===undefined){settings??=await cf(ep(s.name)+'/settings');actual=settings[k];}assert.deepEqual(actual,x,k+' changed');}}
async function verifyNew(s){const v=await version(s.name,s.versionId);await preserved(s,v);assert.deepEqual(hashes(v.modules),s.moduleHashes);return v;}
async function baseline(){if(state.baselineVerifiedAt){await guard();return;}assert.equal(state.owners.length,0,'Inspect incomplete baseline');state.routes=await routes();
for(const d of definitions){const a=await active(d.name);assert.equal(a.id,d.expectedDeployment,'Reconcile newer '+d.name);assert.deepEqual(a.versions,[{version_id:d.expectedVersion,percentage:100}]);const v=await version(d.name,d.expectedVersion),settings=await cf(ep(d.name)+'/settings'),runtime=v.resources?.script_runtime||{},owned='journey-shop-release-20261031/'+d.kind+'.mjs',hs=hashes(v.modules);assert.equal(hs[owned],d.expectedFactory);
const s={name:d.name,kind:d.kind,ownedModule:owned,previousVersion:d.expectedVersion,baselineDeployment:a.id,currentDeployment:a.id,mainModule:v.main_module,bindings:v.bindings,compatibilityDate:v.compatibility_date,compatibilityFlags:v.compatibility_flags||[],assets:v.assets??runtime.assets,operatingConfiguration:{},baselineModuleHashes:hs,schedules:await cf(ep(d.name)+'/schedules')};for(const k of['usage_model','limits','placement','cache_options','observability','tail_consumers','logpush']){const x=v[k]??runtime[k]??settings[k];if(x!==undefined)s.operatingConfiguration[k]=x;}state.owners.push(s);save();}state.baselineVerifiedAt=new Date().toISOString();save();await guard();console.log('BOTH_CURRENT_BASELINES_VERIFIED',state.owners.map(s=>({name:s.name,version:s.previousVersion,entry:s.mainModule,modules:Object.keys(s.baselineModuleHashes).length})));}
async function stage(i){assert(state.baselineVerifiedAt);await guard();const s=state.owners[i];if(s.versionId){await verifyNew(s);return;}assert(!s.uploadIntent,'Unknown previous upload; inspect provider');const source=JSON.parse(readFileSync('first-paint-source.json'));assert.match(source.commit,/^[a-f0-9]{40}$/);if(state.source)assert.equal(state.source,source.commit);state.source=source.commit;const v=await version(s.name,s.previousVersion);await preserved(s,v);assert.deepEqual(hashes(v.modules),s.baselineModuleHashes);const b=readFileSync('bundle-'+s.kind+'.mjs');assert.equal(digest(b),source.bundles[s.kind]);v.modules.find(m=>m.name===s.ownedModule).content_base64=b.toString('base64');s.moduleHashes=hashes(v.modules);assert.deepEqual(Object.keys(s.moduleHashes).filter(k=>s.moduleHashes[k]!==s.baselineModuleHashes[k]),[s.ownedModule]);s.bundleSHA256=digest(b);
const metadata={main_module:s.mainModule,compatibility_date:s.compatibilityDate,compatibility_flags:s.compatibilityFlags,bindings:s.bindings.map(b=>({type:'inherit',name:b.name})),keep_assets:true,...s.operatingConfiguration,annotations:{'workers/message':'Approved My Timber app-first presentation '+state.source,'workers/tag':'first-paint-'+state.source.slice(0,12)}},form=new FormData();form.set('metadata',new Blob([JSON.stringify(metadata)],{type:'application/json'}),'metadata.json');for(const m of v.modules)form.set(m.name,new Blob([Buffer.from(m.content_base64,'base64')],{type:m.content_type||'application/javascript+module'}),m.name);
s.uploadIntent={at:new Date().toISOString(),source:state.source};save();await guard();const u=await cf(ep(s.name)+'/versions?bindings_inheritance=strict','POST',form);s.versionId=u.id;save();await verifyNew(s);await guard();s.stagedVerifiedAt=new Date().toISOString();save();writeFileSync('first-paint-production-state.json',JSON.stringify({source:state.source,owners:state.owners.map(s=>({name:s.name,versionId:s.versionId||s.previousVersion}))},null,2)+'\n');console.log('SCOPED_UPLOAD_VERIFIED',s.name,s.versionId,state.source);}
async function deploy(i,mode){const s=state.owners[i];assert(s.stagedVerifiedAt);await verifyNew(s);const desired=mode==='zero'?[{version_id:s.previousVersion,percentage:100},{version_id:s.versionId,percentage:0}]:[{version_id:s.versionId,percentage:100}],message='My Timber first paint '+state.source+' '+s.kind+' '+mode,before=await active(s.name);
if(before.annotations?.['workers/message']===message&&JSON.stringify(before.versions)===JSON.stringify(desired)){s.currentDeployment=before.id;s[mode+'VerifiedAt']=new Date().toISOString();save();await guard();return;}
await guard();if(mode==='live'){assert(state.candidateAcceptedAt);assert(s.zeroVerifiedAt);if(i===1)assert(state.programmeProductionVerifiedAt,'Verify programme production before dashboard promotion');}assert(!s.deploymentIntent||s.deploymentIntent.finished,'Unknown deployment outcome; inspect provider');s.deploymentIntent={mode,message,previousDeployment:before.id,at:new Date().toISOString(),finished:false};save();const published=await cf(ep(s.name)+'/deployments','POST',{strategy:'percentage',versions:desired,annotations:{'workers/message':message}});s.currentDeployment=published.id;save();const observed=await active(s.name);assert.equal(observed.id,published.id);assert.deepEqual(observed.versions,desired);s[mode+'VerifiedAt']=new Date().toISOString();s.deploymentIntent.finished=true;save();await guard();console.log('PUBLICATION_VERIFIED',s.kind,mode,s.versionId,published.id);}
async function accept(){await guard();assert(state.owners.every(s=>s.zeroVerifiedAt));const files=['first-paint-production-candidate.json','shop-browser-proof/first-paint-served-candidate-chromium-20261101/receipt.json','shop-browser-proof/first-paint-served-candidate-webkit-20261101/receipt.json'];state.acceptance=[];for(const path of files){const b=readFileSync(path),r=JSON.parse(b);if(r.phase){assert(r.verified);assert.equal(r.source,state.source);assert.equal(r.firstPaintChecks?.length,7);}else{assert.equal(r.checks,39);assert(r.results.every(c=>c.pass));assert.equal(r.nativeScriptSha256.length,2);assert.equal(r.productionWrites,0);assert.equal(r.checkoutPosts,0);}state.acceptance.push({path,sha256:digest(b)});}state.candidateAcceptedAt=new Date().toISOString();save();console.log('SERVED_FIRST_PAINT_ACCEPTED',state.source);}
async function acceptProgramme(){await guard();const r=JSON.parse(readFileSync('first-paint-production-programme-live.json'));assert(r.verified);assert.equal(r.source,state.source);assert.equal(r.firstPaintChecks?.length,4);assert(state.owners[0].liveVerifiedAt);state.programmeProductionVerifiedAt=new Date().toISOString();save();console.log('PROGRAMME_PRODUCTION_VERIFIED');}
try{if(phase==='baseline')await baseline();else if(phase==='stage-programme')await stage(0);else if(phase==='stage-documents')await stage(1);else if(phase==='zero-programme')await deploy(0,'zero');else if(phase==='zero-documents')await deploy(1,'zero');else if(phase==='live-programme')await deploy(0,'live');else if(phase==='live-documents')await deploy(1,'live');else if(phase==='accept')await accept();else if(phase==='accept-programme')await acceptProgramme();else if(phase==='status'){for(const d of definitions){const a=await active(d.name);console.log('CURRENT_PROVIDER_STATE',JSON.stringify({name:d.name,id:a.id,versions:a.versions,message:a.annotations?.['workers/message']}));}}else throw Error('Unknown scoped first-paint phase');state.updatedAt=new Date().toISOString();state.lastSuccessfulPhase=phase;delete state.failure;save();}catch(e){state.failure={phase,message:e.message,at:new Date().toISOString()};save();console.error('FIRST_PAINT_RELEASE_STOPPED',e.message);process.exitCode=1;}
